function accept_fix(fix_case, ask) {
  const jobs = fix_case.jobs || [];
  const nearby = fix_case.nearby || [];

  const repaired = jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  const jobNames = new Set(jobs.map(j => j.name));

  function isExactJob(situation, jobName) {
    if (situation === jobName) return true;
    const ref = `job "${jobName}"`;
    const idx = situation.indexOf(ref);
    if (idx === -1) return false;
    const after = situation.slice(idx + ref.length);
    return /^[\s.,;:]*$/.test(after);
  }

  const exactEndings = {};
  for (const n of nearby) {
    for (const j of jobs) {
      if (isExactJob(n.situation, j.name)) {
        exactEndings[j.name] = { before: n.before, after: n.after };
      }
    }
  }

  const correctBefore = new Set();
  const correctAfter = new Set();
  for (const j of jobs) {
    const e = exactEndings[j.name];
    if (e) {
      if (j.before === 'pass') correctBefore.add(e.before);
      if (j.after === 'pass') correctAfter.add(e.after);
    }
  }

  const candidates = [];
  for (const n of nearby) {
    if (n.before === n.after) continue;

    let isExact = false;
    for (const j of jobs) {
      if (isExactJob(n.situation, j.name)) {
        isExact = true;
        break;
      }
    }
    if (isExact) continue;

    let score = 0;
    const text = (n.situation || '').toLowerCase();

    if (/\b(not|without|no)\b/.test(text)) score += 100;

    const jobRefRegex = /job "([^"]+)"/g;
    let match;
    let refsNonJob = false;
    while ((match = jobRefRegex.exec(n.situation || '')) !== null) {
      if (!jobNames.has(match[1])) {
        refsNonJob = true;
        break;
      }
    }
    if (refsNonJob) score += 50;

    if (!/, but /i.test(n.situation) && !/ also /i.test(n.situation)) score += 20;

    if (correctBefore.has(n.before)) score += 10;
    if (correctAfter.has(n.before)) score += 10;
    if (correctAfter.has(n.after)) score -= 10;

    candidates.push({ n, score });
  }

  candidates.sort((a, b) => b.score - a.score);

  let asked = 0;
  for (const { n } of candidates) {
    if (asked >= 3) break;
    const actual = ask(n.id);
    asked++;
    if (actual === null) break;
    if (actual === n.before && actual !== n.after) return false;
  }

  return true;
}

